import{_ as t,o as n,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Video Space: tiến trình dựng + tự đưa lớp lên timeline — spec","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-space-edit-progress-layers/spec.md","filePath":"feature/video-space-edit-progress-layers/spec.md"}'),c={name:"feature/video-space-edit-progress-layers/spec.md"};function o(r,e,h,l,d,s){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="video-space-tien-trinh-dung-tu-đua-lop-len-timeline-—-spec" tabindex="-1">Video Space: tiến trình dựng + tự đưa lớp lên timeline — spec <a class="header-anchor" href="#video-space-tien-trinh-dung-tu-đua-lop-len-timeline-—-spec" aria-label="Permalink to &quot;Video Space: tiến trình dựng + tự đưa lớp lên timeline — spec&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><ol><li>Khi Claude dựng xong, kết quả hiện ngay trên timeline thành các lớp (clip đã cắt, chữ, âm thanh) để người dùng chỉnh tiếp, không phải bấm nút.</li><li>Khi Claude đang dựng, khung chat hiện tiến trình rõ ràng, đẹp: đang ở bước nào, đã làm gì, chạy bao lâu.</li></ol><h2 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h2><p>Là người dựng video, tôi muốn thấy AI đang làm tới đâu và khi xong thì có ngay các lớp trên timeline để sửa tay.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>AC1: Lượt dựng chuyển sang COMPLETED trong lúc người dùng đang mở dự án, có <code>plan.editable = true</code> → tự nhập các lớp vào timeline đúng 1 lần, lưu lên máy chủ, hiện thông báo &quot;Đã đưa các lớp lên timeline&quot; + Ctrl+Z để hoàn tác.</li><li>AC2: Lượt cũ (đã xong trước khi mở trang) KHÔNG tự nhập lại; vẫn có nút &quot;Áp dụng vào timeline&quot;.</li><li>AC3: Lượt chỉ có MP4 (<code>editable = false</code>) không tự nhập; hiện rõ &quot;Bản này chỉ có MP4 liền&quot; như hiện tại.</li><li>AC4: Thẻ tiến trình có: tiêu đề, đồng hồ thời gian đã chạy (mm:ss, tính từ <code>created_at</code>), thanh tiến độ, 4 bước (Nhận yêu cầu → Dựng &amp; chỉnh → Xuất &amp; kiểm tra → Lưu video) với trạng thái xong/đang làm/chờ, danh sách các việc Claude báo (TIEN_DO, 5 dòng mới nhất, dòng mới nhất nổi bật).</li><li>AC5: i18n: chuỗi mới nằm trong <code>autoEditChatMessages</code> (vi + en, key song song) của package <code>vendor/video-space</code> (package này có bộ message riêng, không dùng <code>src/i18n</code>).</li><li>AC6: Light/Dark: chỉ dùng biến theme (<code>--primary</code>, <code>--muted-foreground</code>, <code>--border</code>, <code>--secondary</code>), không hex cố định.</li><li>AC7: <code>prefers-reduced-motion</code> tắt animation.</li></ul><h2 id="ui-states" tabindex="-1">UI states <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI states&quot;">​</a></h2><p>QUEUED/analyzing → bước 1 đang làm · planning → bước 2 (kèm ghi chú) · rendering/qc → bước 3 · uploading → bước 4 · RECONCILIATION_REQUIRED → thông báo kiểm tra lại · FAILED → báo lỗi như cũ.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Sửa backend xuất TIMELINE.json; thanh % chính xác theo thời gian thật (chỉ ước lượng theo bước).</p>',11)])])}const u=t(c,[["render",o]]);export{g as __pageData,u as default};
